  const loadChart=useCallback(async(currentCode=code,tf=timeframe)=>{if(!currentCode)return;try{const data=await request<{candles:Candle[];source:string}>(currentCode,{action:"chart",timeframe:tf});setCandles(data.candles||[]);setChartSource(data.source||"");}catch(e){setCandles([]);setChartSource(e instanceof Error?e.message:"Chart unavailable");}},[code,timeframe]);
  useEffect(()=>{const saved=sessionStorage.getItem("zuperior-arena-code");if(saved)setCode(saved);const handler=(event:Event)=>{event.preventDefault();setInstallPrompt(event as any);};window.addEventListener("beforeinstallprompt",handler);if("serviceWorker" in navigator)navigator.serviceWorker.register("./sw.js").catch(()=>{});return()=>window.removeEventListener("beforeinstallprompt",handler);},[]);
  useEffect(()=>{if(code)void refresh(code);},[code,refresh]);
