  useEffect(()=>{const timer=window.setInterval(()=>setTick(Date.now()),1000);return()=>window.clearInterval(timer);},[]);
  useEffect(()=>{const fn=()=>setChartFullscreen(Boolean(document.fullscreenElement));document.addEventListener("fullscreenchange",fn);return()=>document.removeEventListener("fullscreenchange",fn);},[]);

  const me=state?.me,leaderboard=state?.leaderboard||[];
